-- PostgreSQL 버전 (MariaDB 원본: db/migration/V7__add_user_deleted_at.sql). 버전 번호·순서·결과 스키마는 원본과 같다.
-- AUTO_INCREMENT → GENERATED BY DEFAULT AS IDENTITY, DATETIME(6) → TIMESTAMP(6), DECIMAL → NUMERIC
-- 기존 회원은 NULL(정상 상태)을 유지하고, 탈퇴 시각만 추가로 기록합니다.
ALTER TABLE users ADD COLUMN deleted_at TIMESTAMP(6) NULL;
